create table if not exists public.note_folders ( id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references public.profiles(id) on delete cascade, name text not null check (char_length(btrim(name)) between 1 and 80), created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create unique index if not exists note_folders_owner_name on public.note_folders (owner_id, lower(btrim(name))); create table if not exists public.notes ( id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references public.profiles(id) on delete cascade, folder_id uuid references public.note_folders(id) on delete set null, title text not null check (char_length(btrim(title)) between 1 and 200), body text not null default '' check (char_length(body) <= 20000), created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create index if not exists notes_owner_updated on public.notes (owner_id, updated_at desc); create index if not exists notes_folder on public.notes (folder_id); create table if not exists public.note_checklist_items ( id uuid primary key default gen_random_uuid(), note_id uuid not null references public.notes(id) on delete cascade, owner_id uuid not null default auth.uid() references public.profiles(id) on delete cascade, text text not null check (char_length(btrim(text)) between 1 and 500), done boolean not null default false, position integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create index if not exists note_checklist_items_note on public.note_checklist_items (note_id, position); create index if not exists note_checklist_items_owner_open on public.note_checklist_items (owner_id, done); create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at := now(); return new; end; $$; drop trigger if exists note_folders_touch on public.note_folders; create trigger note_folders_touch before update on public.note_folders for each row execute procedure public.touch_updated_at(); drop trigger if exists notes_touch on public.notes; create trigger notes_touch before update on public.notes for each row execute procedure public.touch_updated_at(); drop trigger if exists note_checklist_items_touch on public.note_checklist_items; create trigger note_checklist_items_touch before update on public.note_checklist_items for each row execute procedure public.touch_updated_at(); create or replace function public.touch_parent_note() returns trigger language plpgsql as $$ begin update public.notes set updated_at = now() where id = coalesce(new.note_id, old.note_id); return null; end; $$; drop trigger if exists note_checklist_items_touch_note on public.note_checklist_items; create trigger note_checklist_items_touch_note after insert or update or delete on public.note_checklist_items for each row execute procedure public.touch_parent_note(); alter table public.note_folders enable row level security; alter table public.notes enable row level security; alter table public.note_checklist_items enable row level security; drop policy if exists "note_folders: owner only" on public.note_folders; create policy "note_folders: owner only" on public.note_folders for all using (owner_id = auth.uid()) with check (owner_id = auth.uid()); drop policy if exists "notes: owner only" on public.notes; create policy "notes: owner only" on public.notes for all using (owner_id = auth.uid()) with check ( owner_id = auth.uid() and ( folder_id is null or exists ( select 1 from public.note_folders f where f.id = folder_id and f.owner_id = auth.uid() ) ) ); drop policy if exists "note_checklist_items: owner only" on public.note_checklist_items; create policy "note_checklist_items: owner only" on public.note_checklist_items for all using (owner_id = auth.uid()) with check ( owner_id = auth.uid() and exists ( select 1 from public.notes n where n.id = note_id and n.owner_id = auth.uid() ) ); revoke all on public.note_folders from anon; revoke all on public.notes from anon; revoke all on public.note_checklist_items from anon; grant select, insert, update, delete on public.note_folders to authenticated; grant select, insert, update, delete on public.notes to authenticated; grant select, insert, update, delete on public.note_checklist_items to authenticated;
